#!/usr/bin/env python3
"""Make deps/<release>.nix from MathWorks' dependency lists.

Reads matlab-deps/<release>/ubuntu24.04/base-dependencies-amd64.txt from
https://github.com/mathworks-ref-arch/container-images, changes each Debian
name to nixpkgs attributes with deps/mapping.nix, and writes one Nix file for
each release. If a name is not in mapping.nix, it writes nothing and lists the
missing names. See deps/README.md.

usage: update-deps.py [--commit SHA] [RELEASE ...]

With no releases, it makes the files that are already in deps/ again.
"""

import argparse
import json
import os
import re
import shutil
import subprocess
import sys
import urllib.error
import urllib.request
from pathlib import Path

REPO = "mathworks-ref-arch/container-images"
DISTRO = "ubuntu24.04"
LIST = "base-dependencies-amd64.txt"


def deps_dir():
    # The script in the repository, or (from `nix run .#update-deps`) a copy in
    # the store, run from the root of the repository.
    here = Path(__file__).resolve().parent
    if (here / "mapping.nix").exists():
        return here
    if (Path.cwd() / "deps" / "mapping.nix").exists():
        return Path.cwd() / "deps"
    sys.exit("update-deps: run this from the root of the matlab-nix repository")


def fetch(url, accept=None):
    request = urllib.request.Request(url)
    if accept:
        request.add_header("Accept", accept)
    token = os.environ.get("GITHUB_TOKEN")
    if token and url.startswith("https://api.github.com/"):
        request.add_header("Authorization", f"Bearer {token}")
    with urllib.request.urlopen(request, timeout=30) as response:
        return response.read().decode()


def latest_commit():
    data = fetch(f"https://api.github.com/repos/{REPO}/commits/main", "application/vnd.github+json")
    return json.loads(data)["sha"]


def read_list(release, commit):
    path = f"matlab-deps/{release}/{DISTRO}/{LIST}"
    try:
        text = fetch(f"https://raw.githubusercontent.com/{REPO}/{commit}/{path}")
    except urllib.error.HTTPError as error:
        sys.exit(f"update-deps: cannot get {path} at {commit[:7]}: {error}")
    names = []
    for line in text.splitlines():
        line = line.split("#", 1)[0].strip()
        if line:
            names.append(line)
    return path, names


def read_mapping(directory):
    result = subprocess.run(
        ["nix", "eval", "--json", "--file", str(directory / "mapping.nix")],
        check=True,
        capture_output=True,
        text=True,
    )
    mapping = json.loads(result.stdout)
    # One attribute path, or a list of them, or null.
    return {name: [] if value is None else [value] if isinstance(value, str) else value for name, value in mapping.items()}


def render(release, path, commit, names, mapping):
    sources = {}
    left_out = []
    for name in names:
        if not mapping[name]:
            left_out.append(name)
        for attr in mapping[name]:
            sources.setdefault(attr, []).append(name)

    lines = [
        "# Generated by deps/update-deps.py. Do not edit this file: change",
        "# deps/mapping.nix and run the script again (see deps/README.md).",
        "#",
        f"# The dependencies of MATLAB {release[0].upper() + release[1:]}, from {path}",
        f"# in https://github.com/{REPO} (commit {commit[:7]}).",
    ]
    if left_out:
        lines.append("# Left out (null in mapping.nix):")
        lines += [f"#   {name}" for name in left_out]
    lines += ["pkgs:", "", "with pkgs;", "["]
    for attr in sorted(sources, key=str.lower):
        debian = ", ".join(sources[attr])
        lines.append(f"  {attr}" if debian == attr else f"  {attr} # {debian}")
    lines += ["]", ""]
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description="Make deps/<release>.nix from MathWorks' dependency lists.")
    parser.add_argument("releases", nargs="*", metavar="RELEASE", help="for example R2026b (default: the releases in deps/)")
    parser.add_argument("--commit", help=f"the commit of {REPO} to read (default: the latest on main)")
    args = parser.parse_args()

    directory = deps_dir()
    releases = [r.lower() for r in args.releases] or sorted(p.stem for p in directory.glob("r20*.nix"))
    for release in releases:
        if not re.fullmatch(r"r20\d\d[ab]", release):
            sys.exit(f"update-deps: {release} is not a release name like R2026b")
    if not releases:
        sys.exit("update-deps: no releases in deps/, so give one or more, for example R2026b")
    if shutil.which("nixfmt") is None:
        sys.exit("update-deps: nixfmt is not on PATH (`nix run .#update-deps` supplies it)")

    mapping = read_mapping(directory)
    commit = args.commit or latest_commit()
    lists = {release: read_list(release, commit) for release in releases}

    missing = sorted({name for _, names in lists.values() for name in names if name not in mapping})
    if missing:
        print("update-deps: these Debian packages are not in deps/mapping.nix:", file=sys.stderr)
        for name in missing:
            releases_with = ["R" + r[1:] for r, (_, names) in lists.items() if name in names]
            print(f"  {name}  ({', '.join(releases_with)})", file=sys.stderr)
        sys.exit("Add them (null to leave one out), then run the script again. Nothing was written.")

    for release, (path, names) in lists.items():
        target = directory / f"{release}.nix"
        target.write_text(render(release, path, commit, names, mapping))
        subprocess.run(["nixfmt", str(target)], check=True)
        print(f"wrote {target.relative_to(Path.cwd()) if target.is_relative_to(Path.cwd()) else target}")


if __name__ == "__main__":
    main()
